"use client";

/**
 * Digit roll: an odometer whose digits spin vertically into place, the ones
 * column first and each column to its left a beat later, with a label under
 * it. A figure that feels counted, not typed.
 *
 * Written by Better Design. Painted from the theme prop, so the digits take
 * the product's ink and the rule under them takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

const ROLL_AT = 6;
/** Frames between one column starting and the next column to its left. */
const STAGGER = 5;
const ROLL_FRAMES = 40;
/** Full turns each column makes before it settles. */
const TURNS = 1;

const FONT_SIZE = 200;
const LINE = FONT_SIZE * 1.2;

export interface DigitRollProps {
  /** The whole number the odometer settles on. Decimals are dropped. */
  value?: number;
  prefix?: string;
  suffix?: string;
  /** One line under the figure that says what it counts. */
  label?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const STRIP = Array.from({ length: 10 * (TURNS + 1) }, (_, i) => i % 10);

/** Roll each digit of a figure into place, right to left, odometer style. */
export function DigitRoll({
  value = 48210,
  prefix = "",
  suffix = "",
  label = "orders delivered this year",
  theme: themeOverride,
  font,
}: DigitRollProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);

  const chars = Math.round(Math.abs(value)).toLocaleString("en-US").split("");
  const digitCount = chars.filter((c) => /\d/.test(c)).length;
  let digitIndex = 0;
  const lastStart = ROLL_AT + (digitCount - 1) * STAGGER;
  const settled = lastStart + ROLL_FRAMES;

  const enter = easings.out(interpolate(frame, [0, 12], [0, 1], clamp));
  const ruleT = easings.out(interpolate(frame, [ROLL_AT, settled], [0, 1], clamp));
  const labelT = easings.out(interpolate(frame, [settled - 10, settled + 8], [0, 1], clamp));
  const sign = value < 0 ? "-" : "";

  const mask = `linear-gradient(to bottom, transparent 0%, black 14%, black 86%, transparent 100%)`;

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 32, opacity: enter }}>
        <div
          style={{
            display: "flex",
            fontSize: FONT_SIZE,
            fontWeight: 700,
            letterSpacing: "-0.04em",
            lineHeight: `${LINE}px`,
            height: LINE,
            color: theme.foreground,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {`${sign}${prefix}` && <span>{`${sign}${prefix}`}</span>}
          {chars.map((c, i) => {
            if (!/\d/.test(c)) {
              return (
                <span key={i} style={{ color: theme.mutedForeground }}>
                  {c}
                </span>
              );
            }
            // Columns start from the right: the ones column moves first.
            const fromRight = digitCount - 1 - digitIndex;
            digitIndex += 1;
            const start = ROLL_AT + fromRight * STAGGER;
            const t = easings.out(interpolate(frame, [start, start + ROLL_FRAMES], [0, 1], clamp));
            const stop = TURNS * 10 + Number(c);
            const y = -stop * LINE * t;
            return (
              <span key={i} style={{ position: "relative", height: LINE, overflow: "hidden", display: "inline-block", WebkitMaskImage: mask, maskImage: mask }}>
                <span style={{ visibility: "hidden" }}>0</span>
                <span style={{ position: "absolute", left: 0, top: 0, display: "flex", flexDirection: "column", transform: `translateY(${y}px)` }}>
                  {STRIP.map((d, k) => (
                    <span key={k} style={{ height: LINE }}>
                      {d}
                    </span>
                  ))}
                </span>
              </span>
            );
          })}
          {suffix && <span style={{ color: theme.mutedForeground }}>{suffix}</span>}
        </div>
        <div style={{ width: "100%", height: 4, borderRadius: 2, background: withAlpha(theme.foreground, 0.08) }}>
          <div style={{ width: `${ruleT * 100}%`, height: "100%", borderRadius: 2, background: theme.primary }} />
        </div>
        <div style={{ fontSize: 44, fontWeight: 500, color: theme.mutedForeground, opacity: labelT, transform: `translateY(${(1 - labelT) * 12}px)` }}>
          {label}
        </div>
      </div>
    </AbsoluteFill>
  );
}
